struct modparams{ui modulus, generator;};
template<modparams const&ref>
struct modular{
	static constexpr ui const& MOD = ref.modulus;
	static modular generator(){ return modular(ref.generator); }
	ui value;
	modular(i64 v = 0){ normalize(v % MOD + MOD); }
	modular& normalize(ui v){
		value = v < MOD ? v : v - MOD;
		return *this;
	}
	modular operator-() const{ return modular() - *this; }
	modular& operator+=(const modular& rhs){ return normalize(value + rhs.value); }
	modular& operator-=(const modular& rhs){ return normalize(value + MOD - rhs.value); }
	modular& operator*=(const modular& rhs){
		value = (ull)value * rhs.value % MOD;
		return *this;
	}
	modular& operator/=(const modular& rhs){ return *this *= rhs.inverse(); }
	modular operator+(const modular& rhs) const{ return modular(*this) += rhs; }
	modular operator-(const modular& rhs) const{ return modular(*this) -= rhs; }
	modular operator*(const modular& rhs) const{ return modular(*this) *= rhs; }
	modular operator/(const modular& rhs) const{ return modular(*this) /= rhs; }
	modular power(int exp) const{
		modular base(*this), result(1);
		while(exp){
			if(exp & 1) result *= base;
			base *= base;
			exp >>= 1;
		}
		return result;
	}
	modular inverse() const{ return power(MOD - 2); }
	friend modular operator+(int x, const modular& y){ return modular(x) + y; }
	friend modular operator-(int x, const modular& y){ return modular(x) - y; }
	friend modular operator*(int x, const modular& y){ return modular(x) * y; }
	friend modular operator/(int x, const modular& y){ return modular(x) / y; }
	friend ostream& operator<<(ostream& os, const modular& m){ return os << m.value; }
	friend istream& operator>>(istream& is, modular& m){ i64 x; is >> x; m = modular(x); return is; }
	bool operator<(const modular& r) const{ return value < r.value; }
	bool operator==(const modular& r) const{ return value == r.value; }
	bool operator!=(const modular& r) const{ return value != r.value; }
	explicit operator bool() const{ return value; }
};

modparams modconfig{998244353, 3};
using mint = modular<modconfig>;

const int MAX_VAL = 10010;
mint factorial[MAX_VAL], inv_factorial[MAX_VAL], inv[MAX_VAL];
void init_factorials(){
	factorial[0] = 1;
	loop(i, 1, MAX_VAL){
		factorial[i] = factorial[i - 1] * i;
	}
	inv_factorial[MAX_VAL - 1] = factorial[MAX_VAL - 1].inverse();
	for(int i = MAX_VAL - 2; i >= 0; --i){
		inv_factorial[i] = inv_factorial[i + 1] * (i + 1);
	}
	for(int i = MAX_VAL - 1; i >= 1; --i){
		inv[i] = inv_factorial[i] * factorial[i - 1];
	}
}
mint nCr(int n, int r){
	return factorial[n] * inv_factorial[n - r] * inv_factorial[r];
}
mint binom(int a, int b){
	return factorial[a + b] * inv_factorial[a] * inv_factorial[b];
}
mint catalan_number(int n){
	return binom(n, n) - (n - 1 >= 0 ? binom(n - 1, n + 1) : 0);
}

void process(){
