	loop(len, 1, m){
		mint term1 = mint(len + 1).power(len) * len / (n - len) * inv_factorial[len];
		repeat(i, m - len){
			int j = i + len;
			mint term2 = mint(n - len).power(i) * inv_factorial[i];
			mint term3 = (n - j) * mint(n + 1).power(m - 1 - j) * factorial[j];
			answer += term1 * term2 * term3;
		}
	}
	answer *= mint(2).power(m - 1) * (n + 1 - m);
